var doc = app.activeDocument;
var o = new IndexedConversionOptions();
o.palette = PaletteType.LOCALSELECTIVE;
o.colors = 32;
o.dither = DitherType.DIFFUSION;
o.ditherAmount = 60;
o.transparency = true;
doc.changeMode(ChangeMode.INDEXEDCOLOR, o);

app.preferences.rulerUnits = Units.PIXELS;
var doc = app.activeDocument, lyr = doc.activeLayer;
var b = lyr.boundsNoEffects;                  // [l, t, r, b]
var w = b[2].as("px") - b[0].as("px");
lyr.translate((doc.width.as("px") - w) / 2 - b[0].as("px"), 0); // centre horizontally
lyr.opacity = 80;
lyr.blendMode = BlendMode.MULTIPLY;

var doc = app.activeDocument;
for (var i = 0; i < doc.layerComps.length; i++) {
  var comp = doc.layerComps[i];
  comp.apply();
  var f = new File("~/Desktop/" + comp.name + ".png");
  doc.saveAs(f, new PNGSaveOptions(), true);
}

function walk(set, pad) {
  for (var i = 0; i < set.layers.length; i++) {
    var l = set.layers[i];
    $.writeln(pad + l.name + " [" + l.typename + "]");
    if (l.typename == "LayerSet") walk(l, pad + "  ");
  }
}
walk(app.activeDocument, "");

var doc = app.activeDocument;
doc.selection.select([[0, 0], [200, 0], [200, 100], [0, 100]]);
doc.recordMeasurements();
var log = app.measurementLog;
log.exportMeasurements(new File("~/Desktop/measure.csv"), MeasurementRange.ALLMEASUREMENTS);
log.deleteMeasurements(MeasurementRange.ALLMEASUREMENTS);

