var files = Folder("~/Desktop/portfolio").getFiles(/\.(jpg|png|psd)$/i);
var o = new PresentationOptions();
o.presentation = false;            // multi-page PDF
o.includeFilename = true;
o.PDFFileOptions = new PDFSaveOptions();
app.makePDFPresentation(files, new File("~/Desktop/portfolio.pdf"), o);

app.preferences.rulerUnits = Units.PIXELS;
var sel = app.activeDocument.selection;
sel.select([[100, 100], [500, 100], [500, 400], [100, 400]]);
sel.feather(12);
var c = new SolidColor(); c.rgb.hexValue = "FF6A00";
sel.fill(c, ColorBlendMode.MULTIPLY, 70);
sel.deselect();

var want = null;
for (var i = 0; i < app.fonts.length; i++) {
  var f = app.fonts[i];
  if (f.family == "Montserrat" && f.style == "Bold") { want = f; break; }
}
if (want) app.activeDocument.activeLayer.textItem.font = want.postScriptName;

app.preferences.rulerUnits = Units.PIXELS; // position is read in ruler units
var doc = app.activeDocument;
var lyr = doc.artLayers.add();
lyr.kind = LayerKind.TEXT;
var t = lyr.textItem;
t.contents = "MONSOON SALE\r50% OFF";
t.font = "Montserrat-Bold"; t.size = 72; t.justification = Justification.CENTER;
t.position = [doc.width.as("px") / 2, 300];

var doc = app.activeDocument;
